SET search_path TO bitpos,public;
CREATE TABLE delegated_owner_challenges(merchant_id uuid NOT NULL REFERENCES merchants(id),id uuid NOT NULL DEFAULT gen_random_uuid(),owner text NOT NULL,domain text NOT NULL,message text NOT NULL,expires_at timestamptz NOT NULL,used_at timestamptz,PRIMARY KEY(merchant_id,id));
CREATE TABLE delegated_owner_sessions(merchant_id uuid NOT NULL REFERENCES merchants(id),id uuid NOT NULL DEFAULT gen_random_uuid(),owner text NOT NULL,domain text NOT NULL,token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,PRIMARY KEY(merchant_id,id));
CREATE TABLE delegated_grants(merchant_id uuid NOT NULL REFERENCES merchants(id),id uuid NOT NULL,policy jsonb NOT NULL,policy_hash text NOT NULL,owner text NOT NULL,source_ata text NOT NULL,delegate text NOT NULL UNIQUE,status text NOT NULL CHECK(status IN ('PREPARED','ACTIVE','PAUSED','REVOKING','REVOKED','EXPIRED','FAILED')),spent numeric(20,0) NOT NULL DEFAULT 0 CHECK(spent>=0),reserved numeric(20,0) NOT NULL DEFAULT 0 CHECK(reserved>=0),approve_signature text,revoke_signature text,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(merchant_id,id),CHECK(spent+reserved<=(policy->>'totalMinor')::numeric));
CREATE UNIQUE INDEX delegated_source_lifecycle ON delegated_grants(source_ata) WHERE status NOT IN ('REVOKED','FAILED');
CREATE TABLE delegated_lifecycle(merchant_id uuid NOT NULL,grant_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('approve','revoke')),unsigned_base64 text NOT NULL,blockhash text NOT NULL,last_valid_height bigint NOT NULL,signed_base64 text,signature text,state text NOT NULL DEFAULT 'PREPARED' CHECK(state IN ('PREPARED','SIGNED','FINALIZED','FAILED','EXPIRED')),PRIMARY KEY(merchant_id,grant_id,kind),FOREIGN KEY(merchant_id,grant_id) REFERENCES delegated_grants(merchant_id,id));
CREATE TABLE delegated_holds(merchant_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),grant_id uuid NOT NULL,order_id uuid NOT NULL,visit_id uuid NOT NULL,session_id uuid NOT NULL,quote_id uuid NOT NULL,nonce uuid NOT NULL,request_hash text NOT NULL,amount numeric(20,0) NOT NULL CHECK(amount>0),attempt_id uuid,state text NOT NULL DEFAULT 'HELD' CHECK(state IN ('HELD','SPENT','RELEASED')),PRIMARY KEY(merchant_id,id),UNIQUE(merchant_id,order_id),UNIQUE(merchant_id,grant_id,nonce),UNIQUE(merchant_id,attempt_id),FOREIGN KEY(merchant_id,grant_id) REFERENCES delegated_grants(merchant_id,id),FOREIGN KEY(merchant_id,order_id) REFERENCES orders(merchant_id,id),FOREIGN KEY(merchant_id,session_id) REFERENCES delegated_owner_sessions(merchant_id,id));
CREATE TABLE delegated_authorizations(merchant_id uuid NOT NULL,attempt_id uuid NOT NULL,unsigned_base64 text NOT NULL,partial_base64 text,PRIMARY KEY(merchant_id,attempt_id),FOREIGN KEY(merchant_id,attempt_id) REFERENCES payment_attempts(merchant_id,id));
ALTER TABLE delegated_holds
 ADD FOREIGN KEY(merchant_id,visit_id) REFERENCES table_visits(merchant_id,id),
 ADD FOREIGN KEY(merchant_id,order_id,quote_id) REFERENCES payment_quotes(merchant_id,order_id,id),
 ADD FOREIGN KEY(merchant_id,order_id,attempt_id) REFERENCES payment_attempts(merchant_id,order_id,id);
CREATE FUNCTION guard_delegated_policy() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.policy IS DISTINCT FROM OLD.policy OR NEW.policy_hash IS DISTINCT FROM OLD.policy_hash OR NEW.owner IS DISTINCT FROM OLD.owner OR NEW.source_ata IS DISTINCT FROM OLD.source_ata OR NEW.delegate IS DISTINCT FROM OLD.delegate THEN RAISE EXCEPTION 'immutable delegated policy'; END IF; RETURN NEW; END $$;
CREATE TRIGGER immutable_delegated_policy BEFORE UPDATE ON delegated_grants FOR EACH ROW EXECUTE FUNCTION guard_delegated_policy();
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['delegated_owner_challenges','delegated_owner_sessions','delegated_grants','delegated_lifecycle','delegated_holds','delegated_authorizations'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant ON %I USING (merchant_id=current_setting(''bitpos.merchant'',true)::uuid) WITH CHECK (merchant_id=current_setting(''bitpos.merchant'',true)::uuid)',t);EXECUTE format('GRANT SELECT,INSERT,UPDATE ON %I TO bitpos_app',t); END LOOP; END $$;
CREATE FUNCTION delegated_work_queue() RETURNS TABLE(merchant_id uuid,grant_id uuid) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=bitpos,pg_temp AS $$
 SELECT g.merchant_id,g.id FROM delegated_grants g WHERE
 EXISTS(SELECT 1 FROM delegated_lifecycle l WHERE l.merchant_id=g.merchant_id AND l.grant_id=g.id AND l.state IN ('PREPARED','SIGNED'))
 OR g.status='ACTIVE' AND (g.policy->>'expiresAt')::timestamptz<=clock_timestamp()
 OR EXISTS(SELECT 1 FROM delegated_holds h WHERE h.merchant_id=g.merchant_id AND h.grant_id=g.id AND h.state='HELD' AND h.attempt_id IS NULL)
 ORDER BY g.created_at LIMIT 100
$$;
REVOKE ALL ON FUNCTION delegated_work_queue() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION delegated_work_queue() TO bitpos_app;
CREATE FUNCTION guard_delegated_hold() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF (NEW.merchant_id,NEW.id,NEW.grant_id,NEW.order_id,NEW.visit_id,NEW.session_id,NEW.quote_id,NEW.nonce,NEW.request_hash,NEW.amount) IS DISTINCT FROM (OLD.merchant_id,OLD.id,OLD.grant_id,OLD.order_id,OLD.visit_id,OLD.session_id,OLD.quote_id,OLD.nonce,OLD.request_hash,OLD.amount) OR OLD.attempt_id IS NOT NULL AND NEW.attempt_id IS DISTINCT FROM OLD.attempt_id OR OLD.state<>'HELD' AND NEW.state IS DISTINCT FROM OLD.state THEN RAISE EXCEPTION 'immutable delegated authorization';END IF;RETURN NEW;END $$;
CREATE TRIGGER immutable_delegated_hold BEFORE UPDATE ON delegated_holds FOR EACH ROW EXECUTE FUNCTION guard_delegated_hold();
